queries.checkoutOwnership:
SELECT json_build_object('mismatch',count(*) FILTER (WHERE
        (c.reservation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM reservations r WHERE r.id=c.reservation_id AND r.user_id=c.user_id AND r.session_id=c.session_id))
        OR c.status='SUBMITTING')) FROM checkout_sessions c WHERE c.user_id LIKE 'perf-user-%' AND substring(c.user_id from '[0-9]+$')::bigint BETWEEN 160102 AND 160102;
